WITH row AS (INSERT INTO zc_private.discord_tournament_message (guild_id,id_tournament,channel_id,message_id,content_hash) VALUES($1,$2,$3,$4,$5) ON CONFLICT(guild_id,id_tournament) DO UPDATE SET channel_id=excluded.channel_id, message_id=excluded.message_id,content_hash=excluded.content_hash,date_updated=clock_timestamp() RETURNING *) SELECT jsonb_build_object('guildId',guild_id::text,'idTournament',id_tournament,'channelId',channel_id::text, 'messageId',message_id::text,'contentHash',content_hash,'dateUpdated',to_char(date_updated AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) AS value FROM row
